<?php
namespace App\Http\Controllers\Webhooks;
use App\Http\Controllers\Controller;use App\Models\Payment;use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Facades\DB;
class TripayWebhookController extends Controller { public function __invoke(Request $request):JsonResponse{$key=(string)config('services.tripay.private_key');$signature=(string)$request->header('X-Callback-Signature');abort_unless($key!==''&&hash_equals(hash_hmac('sha256',$request->getContent(),$key),$signature),403,'Signature tidak valid.');abort_unless(($request->header('X-Callback-Event')??'')==='payment_status',422,'Event tidak valid.');$payload=$request->json()->all();DB::transaction(function()use($payload){$ref=(string)($payload['merchant_ref']??'');$eventKey=hash('sha256',$ref.'|'.($payload['reference']??'').'|'.($payload['status']??''));if(DB::table('payment_webhook_events')->where('event_key',$eventKey)->exists())return;$payment=Payment::where('provider','tripay')->where('merchant_ref',$ref)->lockForUpdate()->firstOrFail();abort_unless((int)($payload['total_amount']??-1)===$payment->total_amount,422,'Nominal tidak cocok.');if($payment->provider_reference)abort_unless(($payload['reference']??'')===$payment->provider_reference,422,'Reference tidak cocok.');$mapped=match(strtoupper((string)($payload['status']??''))){'PAID'=>'paid','FAILED','EXPIRED','REFUND'=>'failed',default=>'unpaid'};$before=$payment->status;if($mapped!=='unpaid'&&$before!==$mapped){$payment->update(['status'=>$mapped,'paid_at'=>$mapped==='paid'?now():$payment->paid_at]);$payment->applicant()->update(['payment_status'=>$mapped,'paid_at'=>$mapped==='paid'?now():null]);DB::table('status_histories')->insert(['applicant_id'=>$payment->applicant_id,'dimension'=>'payment','from_status'=>$before,'to_status'=>$mapped,'note'=>'Callback Tripay terverifikasi','changed_by_type'=>null,'changed_by_id'=>null,'created_at'=>now()]);}DB::table('payment_webhook_events')->insert(['provider'=>'tripay','event_key'=>$eventKey,'provider_reference'=>$payload['reference']??null,'event'=>'payment_status','signature_valid'=>true,'payload_redacted'=>json_encode(array_intersect_key($payload,array_flip(['reference','merchant_ref','payment_method','payment_method_code','total_amount','fee_merchant','fee_customer','status']))),'received_at'=>now(),'processed_at'=>now(),'processing_status'=>'processed','created_at'=>now(),'updated_at'=>now()]);});return response()->json(['success'=>true]);}}
